SELECT FROM emp_employee e LEFT JOIN sys_dept d ON d.dept_id = e.dept_id LEFT JOIN sys_user u ON u.emp_id = e.emp_id
AND e.name LIKE CONCAT('%', #{name}, '%')
AND e.emp_no LIKE CONCAT('%', #{empNo}, '%')
AND e.dept_id = #{deptId}
AND e.status = #{status}
AND e.dept_id IN
#{d}
ORDER BY e.emp_id DESC

SELECT emp_id, emp_no, name, gender, phone, email, dept_id, position, hire_date, status, create_time
FROM emp_employee
WHERE emp_id = #{empId}

